var __defProp=Object.defineProperty;var __export=(target,all)=>{for(var name in all)__defProp(target,name,{get:all[name],enumerable:!0})};var data_exports={};__export(data_exports,{$:()=>$,BUS_M:()=>BUS_M,COARSE:()=>COARSE,CURRENT_YEAR:()=>CURRENT_YEAR,DEFAULTS:()=>DEFAULTS,EIFFEL_M:()=>EIFFEL_M,FIRST_YEAR:()=>FIRST_YEAR,GLACIER_INFO:()=>GLACIER_INFO,HOUSEHOLD_L_DAY:()=>HOUSEHOLD_L_DAY,ICE_2024:()=>ICE_2024,LAKE_ZURICH_KM3:()=>LAKE_ZURICH_KM3,LANDSAT_YEARS:()=>LANDSAT_YEARS,PHONE:()=>PHONE,PITCH_M2:()=>PITCH_M2,POOL_L:()=>POOL_L,SWISS_POP:()=>SWISS_POP,SWISS_SERIES:()=>SWISS_SERIES,SWISS_SUPPLY_KM3:()=>SWISS_SUPPLY_KM3,TRAILS:()=>TRAILS,VOLUME_LOSS:()=>VOLUME_LOSS,YEARS:()=>YEARS,iceVolume:()=>iceVolume,lv95:()=>lv95,lv95f:()=>lv95f});var FIRST_YEAR=2016,CURRENT_YEAR=new Date().getFullYear(),YEARS=Array.from({length:CURRENT_YEAR-2016+1},(_,i)=>2016+i),LANDSAT_YEARS=REGION.landsat?Array.from({length:2016-REGION.landsat.from},(_,i)=>REGION.landsat.from+i):[],SWISS_SERIES=window.GLACIER_DATA&&window.GLACIER_DATA.swiss_volume||[],ICE_2024=(SWISS_SERIES.find(r=>r[0]===2024)||[0,46.4])[1];function iceVolume(year){let row=SWISS_SERIES.find(r=>r[0]===year);if(row)return row[1];let v=ICE_2024;if(year<2024)for(let y=2024;y>year;y--){let n=VOLUME_LOSS.find(d=>d.y===y);v=v/(1-(n?n.v:0)/100)}if(year>2024)for(let y=2025;y<=year;y++){let n=VOLUME_LOSS.find(d=>d.y===y);v=v*(1-(n?n.v:0)/100)}return v}var EIFFEL_M=330,PITCH_M2=7140,BUS_M=12,LAKE_ZURICH_KM3=3.9,POOL_L=25e5,SWISS_SUPPLY_KM3=.931,HOUSEHOLD_L_DAY=142,SWISS_POP=9e6,VOLUME_LOSS=[{y:2016,v:1.5,approx:!0},{y:2017,v:3},{y:2018,v:2.5},{y:2019,v:2,approx:!0},{y:2020,v:2,approx:!0},{y:2021,v:1,approx:!0},{y:2022,v:5.9},{y:2023,v:4.4},{y:2024,v:2.4},{y:2025,v:3},{y:2026,v:5.5}];SWISS_SERIES.forEach(([y,,pct])=>{if(y<2016||pct==null)return;let row=VOLUME_LOSS.find(n=>n.y===y),v=-pct;row?(row.v=v,delete row.approx):VOLUME_LOSS.push({y,v})});VOLUME_LOSS.sort((a,b)=>a.y-b.y);var DEFAULTS=[{id:"aletsch",tongue:[46.424,8.032],keys:["grosser aletsch"],name:"Grosser Aletsch",local:"Grosser Aletschgletscher",canton:"Valais",range:"Bernese Alps",center:[46.47,8.04],bounds:[[46.4,7.95],[46.56,8.12]],a1850:105.6,a1973:86.6,a2016:78.49,aNew:[75.79,2023],len:[26.5,24,22.6],lede:"The largest glacier in the Alps. Several firn streams meet at Konkordiaplatz before the tongue curves south-west towards the Massa gorge above Brig.",look:"Follow the tongue south of the bend at M\xE4rjelen and compare where clean ice gives way to grey rock. The dark medial moraines running down the middle are easy to follow from year to year.",note:'In summer 2026 almost six metres of ice disappeared at one measuring point at Konkordiaplatz, about as much as in the extreme year 2022. This is a single point, not an average of the whole glacier.<small class="srcline">Source: GLAMOS, reported by wetter.net (September 2026)</small>'},{id:"gorner",tongue:[45.978,7.778],keys:["gorner"],name:"Gorner",local:"Gornergletscher",canton:"Valais",range:"Pennine Alps",center:[45.95,7.81],bounds:[[45.9,7.72],[46,7.9]],a1850:66,a1973:59.7,a2016:41.24,aNew:[35.37,2023],len:[15.9,13.5,12.4],lede:"The second-largest glacier in Switzerland by area, flowing west from Monte Rosa towards Zermatt. Its main tributary is the Grenzgletscher.",look:"Look at the confluence with the Grenzgletscher, where the ice-marginal Gornersee forms.",note:""},{id:"fiescher",tz:14,tongue:[46.468,8.145],keys:["fiescher"],name:"Fiescher",local:"Fieschergletscher",canton:"Valais",range:"Bernese Alps",center:[46.49,8.15],bounds:[[46.42,8.08],[46.57,8.22]],a1850:37.4,a1973:34.2,a2016:29.75,aNew:[28.51,2023],len:[17.1,15.4,14.7],lenYear:2012,lede:"The second-longest glacier in the Alps, draining south from the Finsteraarhorn and Gross Fiescherhorn towards the village of Fiesch in the Goms valley.",look:"Follow the narrow lower tongue towards Fiesch and watch the bare rock along its flanks.",note:""},{id:"unteraar",tongue:[46.563,8.252],keys:["unteraar"],name:"Unteraar",local:"Unteraargletscher",canton:"Bern",range:"Bernese Alps",center:[46.56,8.24],bounds:[[46.51,8.12],[46.61,8.33]],a1850:33.4,a1973:29.5,a2016:22.7,aNew:[20.36,2024],len:[14.5,12.9,11.8],lede:"Formed where the Finsteraar and Lauteraar glaciers merge, the Unteraar flows east into the Grimselsee, the reservoir behind the Grimsel hydropower dams.",look:"Debris covers nearly the whole tongue, so it looks grey rather than white. Watch the front near the lake and the dark central moraine where the two source glaciers join.",note:'The debris cover is typically 5 to 15 cm thick and acts like an insulating layer, so mass loss is somewhat slowed.<small class="srcline">Source: Wikipedia (Unteraargletscher)</small>',sceneNote:"Because shade covers the tongue in September and October, most images of this glacier are from August."},{id:"oberaletsch",tz:14.25,tongue:[46.414,7.992],keys:["oberaletsch"],name:"Oberaletsch",local:"Oberaletschgletscher",canton:"Valais",range:"Bernese Alps",center:[46.43,7.98],bounds:[[46.39,7.9],[46.48,8.05]],a1850:26.6,a1973:22.8,a2016:17.05,aNew:null,len:[10.4,9.1,8.8],lenYear:2011,lede:"Until about 1880 a tributary of the Great Aletsch. Both glaciers have since retreated so far that they no longer meet.",look:"Compare the gap between the Oberaletsch tongue and the Great Aletsch, and the Beich glacier, the western arm that joins it.",note:""},{id:"corbassiere",tz:14.25,tongue:[45.987,7.296],keys:["corbassiere"],name:"Corbassi\xE8re",local:"Glacier de Corbassi\xE8re",canton:"Valais",range:"Pennine Alps",center:[45.97,7.3],bounds:[[45.92,7.24],[46.03,7.36]],a1850:20.7,a1973:18.3,a2016:14.95,aNew:[14.08,2023],len:[12.9,10.1,9.6],lede:"A long valley glacier flowing north from the Grand Combin above the Val de Bagnes, 9.8 km long.",look:"Follow the narrow lower tongue and the moraine walls it has left along its sides.",note:""},{id:"morteratsch",tz:14.5,tongue:[46.421,9.931],keys:["morteratsch"],name:"Morteratsch",local:"Vadret da Morteratsch",canton:"Graub\xFCnden",range:"Bernina Range",center:[46.41,9.93],bounds:[[46.37,9.86],[46.46,9.99]],a1850:19.3,a1973:16.4,a2016:14.93,aNew:null,len:[8.9,7,6.2],lede:"Flowing north from Piz Bernina in the Engadin. Together with the Pers glacier from Piz Pal\xFC it drains via the Inn into the Danube and the Black Sea.",look:"The tongue is reached on foot from Morteratsch station; time panels along the glacier trail show where the ice stood in past years. Compare the tongue tip and the junction with the Pers glacier.",note:'Of the ten glaciers here it is the only one that drains to the Black Sea; the others drain to the North Sea or the Mediterranean.<small class="srcline">Source: Wikipedia (Morteratsch Glacier)</small>'},{id:"zmutt",tz:14.25,tongue:[45.99,7.672],keys:["zmutt"],name:"Zmutt",local:"Zmuttgletscher",canton:"Valais",range:"Pennine Alps",center:[45.99,7.62],bounds:[[45.95,7.54],[46.03,7.7]],a1850:19.8,a1973:16.9,a2016:14.82,aNew:null,len:[8.6,6.7,null],lenYear:null,lede:"Flowing east below the north face of the Matterhorn towards Zermatt, fed by the Tiefmatten and Stockji glaciers.",look:"Most of the lower tongue is covered in debris and looks like a rocky valley floor. Use the bright ice upstream and the reservoir at Zmutt as reference points.",note:""},{id:"rhone",tz:14.5,tongue:[46.588,8.385],keys:["rhone"],name:"Rhone",local:"Rhonegletscher",canton:"Valais",range:"Urner Alps",center:[46.61,8.39],bounds:[[46.56,8.33],[46.66,8.44]],a1850:20.2,a1973:17.6,a2016:14.64,aNew:null,len:[9.2,8,7.7],lede:"The source of the river Rh\xF4ne, flowing south below the Dammastock towards Gletsch, between the Furka and Grimsel passes.",look:"A lake has formed where the tongue used to lie on the rock step above Gletsch. Compare its size and the bare rock around it from year to year.",note:'In summer 2026 the Rh\xF4ne glacier lost more than four metres of ice in a single month. Meltwater has carved cavities under the tongue that collapse into pits.<small class="srcline">Source: Euronews, 7 August 2026 (Matthias Huss, GLAMOS)</small>'},{id:"trift",tz:14.5,tongue:[46.678,8.364],keys:["trift"],name:"Trift",local:"Triftgletscher (Gadmen)",canton:"Bern",range:"Urner Alps",center:[46.67,8.36],bounds:[[46.63,8.3],[46.72,8.43]],a1850:19.3,a1973:16.5,a2016:14.56,aNew:null,len:[7.6,5.8,3.7],lede:"A glacier above the Gadmen valley whose tongue sank into a growing lake in the early 2000s, leaving the Triftsee, spanned by a suspension bridge.",look:"The lake below the steep ice fall is the best marker for how far the tongue has retreated.",note:""}],TRAILS={aletsch:{hike:{title:"Aletsch Panoramaweg (route 39)",text:"Belalp to Riederalp, high above the glacier with several viewpoints. Passes 1.3 km from the tongue.",url:"https://schweizmobil.ch/en/hiking-in-switzerland/route-39",kind:"wander"},bike:{title:"Moosfluh Enduro (mountain bike route 131)",text:"From the Moosfluh viewpoint down to M\xF6rel. Passes 1.4 km from the tongue.",url:"https://schweizmobil.ch/en/mountainbiking-in-switzerland/route-131",kind:"mtb"}},gorner:{hike:{title:"Gornergrat to Riffelberg",text:"From the Gornergrat down past the Riffelsee: 4.7 km, about 1 h 25 min, T2.",url:"https://wegwandern.ch/wanderung/wanderung-gornergrat-zermatt-rotenboden-riffelsee-riffelberg-wandern/",kind:"wander"},bike:null},fiescher:{hike:{title:"Aletsch Panoramaweg, M\xE4rjelensee to Bellwald (route 39)",text:"Stage 3 of the Aletsch Panoramaweg, M\xE4rjelensee to Bellwald. Passes 0.6 km from the tongue tip (computed from the route data).",url:"https://schweizmobil.ch/en/hiking-in-switzerland/route-39",kind:"wander"},bike:{title:"Valais Panorama Bike (mountain bike route 81)",text:"A four-stage tour through the Goms (Conches valley). 2.9 km from the tongue tip (computed from the route data).",url:"https://schweizmobil.ch/en/mountainbiking-in-switzerland/route-81",kind:"mtb"}},unteraar:{hike:{title:"Grimsel Hospiz to the Lauteraarh\xFCtte",text:"Along the Grimselsee to the hut above the glacier: 10.2 km, about 4 h.",url:"https://www.interlaken.swiss/erlebnisse/tour/wandern-am-ursprung-der-aare",kind:"wander"},bike:null},corbassiere:{hike:{title:"Cabane FXB Panossi\xE8re, Col des Otanes to Mauvoisin",text:"From the Cabane FXB Panossi\xE8re over the Col des Otanes down to Mauvoisin, with views of the Corbassi\xE8re glacier: 6.8 km, about 2 h 35 min, T3.",url:"https://wegwandern.ch/wanderung/cabane-fxb-panossiere-col-des-otanes-mauvoisin/",kind:"wander"},bike:null},zmutt:{hike:{title:"Zermatt to the Sch\xF6nbielh\xFCtte",text:"Through the gravel and scree of the retreating glacier, with the Matterhorn in view: 11 km, about 4 h.",url:"https://www.bergwelten.com/t/w/24489",kind:"wander"},bike:null},rhone:{hike:{title:"Furka-H\xF6henweg, Oberwald to the Furkapass (route 51)",text:"First stage of the Furka-H\xF6henweg, Oberwald to the Furkapass, with views of the Rh\xF4ne glacier. Passes 1.4 km from the tongue.",url:"https://schweizmobil.ch/en/hiking-in-switzerland/route-51",kind:"wander"},bike:{title:"Rhone-Route (Veloland route 1)",text:"Starts in Andermatt; the first stage climbs the Furka Pass. Passes 0.7 km from the tongue.",url:"https://schweizmobil.ch/en/cycling-in-switzerland/route-1",kind:"velo"}},trift:{hike:{title:"Triftbr\xFCcke",text:"A 170 m suspension bridge over the lake that the meltwater of the Trift glacier formed: about 1.5 h from the top station.",url:"https://www.myswitzerland.com/en-gb/experiences/route/trift-bridge-a-spectacular-pedestrian-bridge/",kind:"wander"},bike:null},fee:{hike:{title:"L\xE4ngfluh to Saas-Fee",text:"From the L\xE4ngfluh mountain station along the glaciers back to the village: 6.5 km, about 2 h 15 min.",url:"https://www.bergfex.com/sommer/wallis/touren/wanderung/599056,laengfluh--saas-fee",kind:"wander"},bike:null},findel:{hike:{title:"Naturweg, Riffelalp to Sunnegga",text:"Through a stone-pine forest to the retreating glacier, with Matterhorn views: 6.2 km, about 1 h 40 min.",url:"https://zermatt.swiss/p/naturweg-nr-19-01tVj000005EvuoIAC",kind:"wander"},bike:null}},lv95f=(lon,lat)=>{let p=(lat*3600-169028.66)/1e4,l=(lon*3600-26782.5)/1e4;return[260007237e-2+211455.93*l-10938.51*l*p-.36*l*p*p-44.54*l**3,120014707e-2+308807.95*p+3745.25*l*l+76.63*p*p-194.56*l*l*p+119.79*p**3]},lv95=(lon,lat)=>lv95f(lon,lat).map(Math.round),GLACIER_INFO={aletsch:{fact:"The Aletsch region has its own legend: the Rollibock, a large buck with long horns, fiery eyes and icicles instead of fur, who lives in the eternal ice of the Great Aletsch Glacier. He rarely leaves it, only when someone provokes his anger. In one story a hunter from the Fieschertal, who had destroyed rock crystals and killed a chamois doe and her kid, is taken across Lake M\xE4rjelen by a ferryman who turns out to be the Rollibock: the glacier opens and the boat sinks in the icy water. Today he is more a mascot of the region than a legendary figure.",name:"The name Aletsch is first recorded in 1231 as <em>Alech</em>; its origin is unclear.",factSrc:"Bergwelten (Rollibock legend); Alpenverein (Rollibock, mascot)",src:"Historical Dictionary of Switzerland (Aletschgletscher)"},gorner:{fact:"Its ice-marginal lake, the Gornersee, fills every year and usually drains in summer in a glacial lake outburst flood. With its tributaries it forms the second-largest glacier system in the Alps after the Aletsch (53 km\xB2, 2007).",name:`Same name as the Gornergrat beside it. The Gornergrat Bahn's history of that name: as early as 1579 the farmers' guild regulated when sheep could be left on the <em>Gorneren</em>. The historian F. A. Volmar (1958) assumed that the name is a Germanisation of Romansh <em>cornu</em>, "horned", referring to the <em>Gornerhorn</em>: in the first half of the 19th century the people of Zermatt still called the mountains on the Italian side of Monte Rosa the Gornerhorn.`,factSrc:"Wikipedia (Gorner Glacier)",src:"Gornergrat Bahn (gornergrat.ch: how the Gornergrat got its name; the history of tourism access)"},fiescher:{fact:"In 1678 the people of Fiesch vowed to live virtuously and to pray that the Aletsch glacier would stop growing: it had come threateningly close to Fiesch. In August 2010 the Vatican approved a change of the vow: the parish may now include global warming, climate change and glacier melt in its annual prayers.",name:'"Of Fiesch": named after the village and valley below it. The village appears as <em>Vios</em> in 1203 and <em>Viesch</em> in 1438.',factSrc:'Beobachter ("Um Gottes willen"); swissinfo.ch',src:"Historical Dictionary of Switzerland (Fiesch)"},unteraar:{fact:'In the 19th century the naturalists Franz Josef Hugi and Louis Agassiz spent many months here. Agassiz and his team lived under a huge boulder on the medial moraine, which they named the "H\xF4tel des Neuch\xE2telois", while they studied the glacier. It was one of the first subjects of glaciology.',name:'"Lower Aare glacier": the larger of the two sources of the river Aare. The Aare is the longest river that both rises and ends entirely within Switzerland: its total length from source to its junction with the Rhine comprises about 295 kilometres.',factSrc:"swisseduc.ch (Unteraargletscher excursion: Hugi and Agassiz, H\xF4tel des Neuch\xE2telois); Wikipedia (Unteraargletscher: one of the first subjects of developing glaciology)",src:"Wikipedia (Unteraargletscher); Wikipedia (Aare)"},oberaletsch:{fact:"Until about 1880 it still flowed into the Aletsch glacier. Both glaciers have retreated so far that they no longer join.",name:'"Upper Aletsch glacier" (German <em>Ober-</em>, upper): it shares its name with the Aletsch glacier it once joined.',factSrc:"Wikipedia (Oberaletsch Glacier)",src:"Wikipedia (Oberaletsch Glacier)"},corbassiere:{fact:"It starts above 4,000 m on the north slope of the Grand Combin and its tongue ends at about 2,300 m. It is 9.8 km long.",name:"A French place name of the Val de Bagnes; its origin is not documented in the sources I checked.",factSrc:"Wikipedia (Corbassi\xE8re Glacier)",src:"Wikipedia (Corbassi\xE8re Glacier)"},morteratsch:{fact:"With about 1.2 km\xB3 of ice it is the third-largest glacier in the Eastern Alps, after the Pasterze and the Gepatschferner.",name:`A legend explains the name: Annetta, a farmer's daughter, died of sorrow while her beloved herdsman Aratsch was away as a soldier. When he returned he rode into a crevasse, and her ghost is said to wander the alp crying "Mort Aratsch!" ("Aratsch is dead"). A documented etymology is not in the sources I checked.`,factSrc:"Wikipedia (Morteratsch Glacier)",src:"Wikipedia (Morteratsch Glacier); Pontresina Tourism (Legends in the Bernina glacier region)"},zmutt:{fact:"Debris now covers about 32 % of the glacier surface, up from about 13 % in 1859. This debris slowed the glacier's response: its length and area have changed little compared with debris-free glaciers, although the mass loss is similar. The meltwater of the Zmutt glacier feeds the Stafel pumping station of the Grande Dixence system, at 2,180 metres at the foot of the Matterhorn.",name:"Named after the hamlet of Zmutt in the municipality of Zermatt. The origin of the name is not documented in the sources I checked.",factSrc:"The Cryosphere 13 (2019), M\xF6lg et al., Zmuttgletscher study; Grande Dixence SA (Stafel pumping station)",src:"Wikipedia (Zmutt)"},rhone:{fact:"An ice tunnel in the Rh\xF4ne glacier, re-carved every spring, let visitors immerse themselves in the heart of the glacier, attracting up to 100,000 visitors per year. Plastic tarpaulins were spread over the glacier tongue to slow its melting. On 5 September 2026 swissinfo reported that the Valais cantonal government had rejected the operator's appeal against the order to close the cave and restore the site to its original condition. Can you spot the tarpaulins on the tongue in the images?",name:'From the river it feeds: the Rh\xF4ne, which continues the Latin <em>Rhodanus</em> (Greek <em>Rhodan\xF3s</em>). The Gaulish name of the river was <em>*Rodonos</em> or <em>*Rotonos</em>, from a root meaning "to run, roll".',factSrc:'<a href="https://www.swissinfo.ch/eng/glaciers-permafrost/swiss-rh%C3%B4ne-glacier-ice-cave-ordered-closed/92010080" target="_blank" rel="noopener">swissinfo.ch, 5 September 2026</a>',src:"Wikipedia (Rh\xF4ne)"},trift:{fact:"In the 2004/05 measuring year the Trift glacier retreated by 216 m, more than any other monitored glacier in Switzerland, because its tongue ended in a lake that sped up the melting. A suspension bridge about 170 m long (opened 2009, replacing one built in 2004) spans the Triftsee so hikers can still reach the hut.",name:'German <em>Trift</em> is, regionally, a path used by livestock between pasture and stable; the word comes from Middle High German <em>trift</em>, from <em>treiben</em>, "to drive".',factSrc:"plattformj.ch (glacier measurements, 2006); Wikipedia (Trift Bridge)",src:"Duden"},fee:{fact:"At Mittelallalin, 3,500 m high, glaciologist Benedikt Schnyder carved an artificial ice cave into the glacier: the Ice Pavilion, 5,500 m\xB2 with a 71 m tunnel. It closed in 2024 for safety reasons; a virtual reality experience replaced it.",name:"Named after Saas-Fee, the village below it, which appears as <em>Vee</em> in 1304. Where the name itself comes from is not documented in the sources I checked.",factSrc:"showcaves.com (Eispavillon Mittelallalin)",src:"Wikipedia (Saas-Fee)"},findel:{fact:"Around the middle of the 19th century its tongue still reached down to about 2,100 m, near the hamlet of Findeln and below the tree line. Since then it has retreated by more than 2.5 km, and since the 1970s by more than 1 km. Its meltwater, the Findelbach, joins the Gornera and the Zmuttbach to form the Matter Vispa.",name:"Named after the hamlet of Findeln, 2 km east of Zermatt at 2,051 m, near where the tongue once ended. The origin of the name Findeln itself is not documented in the sources I checked.",factSrc:"Wikipedia, German edition (Findelgletscher)",src:"Wikipedia, German edition (Findeln)"}},COAR